import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    # Smallest prime factors for all possible input values.
    spf = list(range(1001))
    for i in range(2, 32):
        if spf[i] == i:
            for j in range(i * i, 1001, i):
                if spf[j] == j:
                    spf[j] = i

    valuations = {}
    for i, value in enumerate(a):
        while value > 1:
            p = spf[value]
            exponent = 0
            while value % p == 0:
                value //= p
                exponent += 1
            valuations.setdefault(p, [0] * (n - 1))[i] = exponent

    answer = 1
    for p, differences in valuations.items():
        bound = sum(differences)
        powers = [1] * (bound + 1)
        for h in range(1, bound + 1):
            powers[h] = powers[h - 1] * p % MOD

        # dp_no_zero[h] and dp_has_zero[h] are weighted sums of prefixes
        # ending at height h, with the indicated zero-visit condition.
        dp_no_zero = [0] * (bound + 1)
        dp_has_zero = [0] * (bound + 1)
        for h in range(1, bound + 1):
            dp_no_zero[h] = powers[h]
        dp_has_zero[0] = 1

        for step in differences:
            next_no_zero = [0] * (bound + 1)
            next_has_zero = [0] * (bound + 1)
            for h in range(bound + 1):
                # Avoid counting the same transition twice when step is zero.
                next_heights = (h,) if step == 0 else (h - step, h + step)
                for nh in next_heights:
                    if 0 <= nh <= bound:
                        weight = powers[nh]
                        next_has_zero[nh] = (next_has_zero[nh] + dp_has_zero[h] * weight) % MOD
                        if nh == 0:
                            next_has_zero[nh] = (next_has_zero[nh] + dp_no_zero[h] * weight) % MOD
                        else:
                            next_no_zero[nh] = (next_no_zero[nh] + dp_no_zero[h] * weight) % MOD
            dp_no_zero, dp_has_zero = next_no_zero, next_has_zero

        contribution = sum(dp_has_zero) % MOD
        answer = answer * contribution % MOD

    print(answer)

if __name__ == '__main__':
    main()

