import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    arr = data[1:1 + n]
    mx = max(arr)

    spf = list(range(mx + 1))
    for p in range(2, int(mx ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, mx + 1, p):
                if spf[x] == x:
                    spf[x] = p

    nim_sum = 0
    for value in arr:
        prime_factor_count = 0
        while value > 1:
            value //= spf[value]
            prime_factor_count += 1
        nim_sum ^= prime_factor_count

    print('Anna' if nim_sum else 'Bruno')

if __name__ == '__main__':
    main()

