import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, k = data[:3]
    a = data[3:]

    # Build a basis for the XOR span and express each input in that basis.
    basis = [0] * 20
    for x in a:
        y = x
        for b in range(19, -1, -1):
            if (y >> b) & 1:
                if basis[b]:
                    y ^= basis[b]
                else:
                    basis[b] = y
                    break

    pivots = [b for b in range(20) if basis[b]]
    r = len(pivots)
    # Convert each value to coordinates in the basis.
    coord_basis = [0] * 20
    for j, b in enumerate(pivots):
        v = basis[b]
        for i in range(j):
            if (v >> pivots[i]) & 1:
                v ^= basis[pivots[i]]
        basis[b] = v
        coord_basis[b] = 1 << j

    vals = []
    for x in a:
        y = x
        c = 0
        for b in range(19, -1, -1):
            if (y >> b) & 1:
                y ^= basis[b]
                c ^= coord_basis[b]
        vals.append(c)

    size = 1 << r
    # dp[residue][xor] counts subsets; process every item.
    dp = [[0] * size for _ in range(m)]
    dp[0][0] = 1
    for x in vals:
        for rem in range(m - 1, -1, -1):
            src = dp[rem]
            dst = dp[(rem + 1) % m]
            # Descending residue is not a valid in-place update for cyclic residues.
            # Use a snapshot of the source row to preserve the 0/1 choice.
            old = src[:]
            for z, count in enumerate(old):
                if count:
                    dst[z ^ x] = (dst[z ^ x] + count) % MOD

    # Convert coordinate XORs back to their integer values and sum moments.
    answer = 0
    row = dp[0]
    for c, count in enumerate(row):
        if count:
            x = 0
            for j, b in enumerate(pivots):
                if (c >> j) & 1:
                    x ^= basis[b]
            answer = (answer + count * pow(x, k, MOD)) % MOD
    # Exclude the empty subsequence when it qualifies. Its score is 0^K = 0,
    # so this does not change the sum.
    print(answer)

if __name__ == '__main__':
    main()

