from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            at[b].append((a, i))

        heap = []
        gain = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in at[right]:
                heapq.heappush(heap, (-left, idx))

            if not heap:
                total += right
                continue

            neg_left, idx = heapq.heappop(heap)
            largest = -neg_left
            second = -heap[0][0] if heap else 0
            heapq.heappush(heap, (neg_left, idx))

            total += right - largest
            gain[idx] += largest - second

        return total + max(gain)

