from typing import List
import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at=[[] for _ in range(n+1)]
        for i,(a,b) in enumerate(conflictingPairs):
            if a>b:a,b=b,a
            at[b].append((a,i))
        h=[]
        gain=[0]*len(conflictingPairs)
        base=0
        for r in range(1,n+1):
            for a,i in at[r]: heapq.heappush(h,(-a,i))
            if h:
                x,i=heapq.heappop(h)
                a=-x
                if h: second=-h[0][0]
                else: second=0
                heapq.heappush(h,(x,i))
                base+=r-a
                gain[i]+=a-second
            else: base+=r
        return base+max(gain)

