import sys

def main():
    input=sys.stdin.buffer.readline
    n,m,q=map(int,input().split())
    edges=[]
    for _ in range(m):
        a,b,c=map(int,input().split()); edges.append((a-1,b-1,c))
    queries=[]; closed=set()
    for _ in range(q):
        z=list(map(int,input().split()))
        if z[0]==1:
            i=z[1]-1; queries.append((1,i)); closed.add(i)
        else: queries.append((2,z[1]-1,z[2]-1))
    inf=10**30
    d=[[inf]*n for _ in range(n)]
    for i in range(n): d[i][i]=0
    for eid,(a,b,c) in enumerate(edges):
        if eid not in closed: d[a][b]=d[b][a]=c
    for k in range(n):
        dk=d[k]
        for i in range(n):
            dik=d[i][k]
            if dik==inf: continue
            di=d[i]
            for j in range(n):
                v=dik+dk[j]
                if v<di[j]: di[j]=v
    ans=[]
    for qu in reversed(queries):
        if qu[0]==2:
            v=d[qu[1]][qu[2]]
            ans.append(str(v if v<inf else -1))
        else:
            a,b,c=edges[qu[1]]
            col_a=[d[i][a] for i in range(n)]
            col_b=[d[i][b] for i in range(n)]
            row_a=d[a][:]; row_b=d[b][:]
            for i in range(n):
                da=col_a[i]; db=col_b[i]; di=d[i]
                for j in range(i,n):
                    v=di[j]
                    x=da+c+row_b[j]
                    if x<v: v=x
                    x=db+c+row_a[j]
                    if x<v: v=x
                    di[j]=v
                    d[j][i]=v
    print('\n'.join(reversed(ans)))

if __name__=='__main__': main()

