class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (x + 1)
        dp[0] = 1

        for _ in range(n):
            ndp = [0] * (x + 1)
            for k, ways in enumerate(dp):
                if ways:
                    # Place this performer on one of the k occupied stages.
                    ndp[k] = (ndp[k] + ways * k) % MOD
                    # Or open a previously unused stage and choose its score.
                    if k < x:
                        ndp[k + 1] = (ndp[k + 1] + ways * (x - k) * y) % MOD
            dp = ndp

        return sum(dp) % MOD

