class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)

        # Binomial coefficients modulo MOD.
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact = [1] * (n + 1)
        invfact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        def choose(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

        # Number of popcount operations needed to reduce each value to 1.
        depth = [0] * (n + 1)
        for x in range(2, n + 1):
            depth[x] = 1 + depth[x.bit_count()]

        answer = 0
        for ones in range(1, n + 1):
            # For a number with 'ones' bits set, the first operation gives
            # 'ones'. (The case ones == 1 is already 1 after that operation.)
            if ones != 1 and depth[ones] > k - 1:
                continue

            used = 0
            count = 0
            for i, bit in enumerate(s):
                if bit == '1':
                    remaining = n - i - 1
                    count += choose(remaining, ones - used)
                    if count >= MOD:
                        count -= MOD
                    used += 1
            answer = (answer + count) % MOD

        return answer

