import sys
from collections import deque

def main():
    input=sys.stdin.readline
    n=int(input())
    g=[input().strip() for _ in range(n)]
    inc=[[[] for _ in range(26)] for _ in range(n)]
    out=[[[] for _ in range(26)] for _ in range(n)]
    short=[1<<i for i in range(n)]
    for i in range(n):
        for j,ch in enumerate(g[i]):
            if ch!='-':
                c=ord(ch)-97
                out[i][c].append(j)
                inc[j][c].append(i)
                short[i] |= 1<<j
    inf=10**9
    d=[[inf]*n for _ in range(n)]
    q=deque()
    for i in range(n):
        d[i][i]=0
        q.append((i,i))
    for i in range(n):
        for j,ch in enumerate(g[i]):
            if ch!='-' and d[i][j]>1:
                d[i][j]=1
                q.append((i,j))
    while q:
        u,v=q.popleft()
        nd=d[u][v]+2
        for c in range(26):
            xs=inc[u][c]
            ys=out[v][c]
            if not xs or not ys:
                continue
            if nd>=2:
                ymask=0
                for y in ys:
                    ymask |= 1<<y
                if all((ymask & ~short[x]) == 0 for x in xs):
                    continue
            for x in xs:
                row=d[x]
                for y in ys:
                    if nd<row[y]:
                        row[y]=nd
                        q.append((x,y))
    print('\n'.join(' '.join(str(x if x<inf else -1) for x in row) for row in d))
