from itertools import product

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, K = data[:3]
    X = tuple(data[3:3 + M])

    # Small instances: directly enumerate candidate strings and their
    # length-M subsequences.
    if K ** N <= 2_000_000:
        ans = 0
        for a in product(range(1, K + 1), repeat=N):
            seen = set()
            for inds in __import__('itertools').combinations(range(N), M):
                seen.add(tuple(a[i] for i in inds))
                if len(seen) == K ** M:
                    break
            if len(seen) == K ** M - 1 and X not in seen:
                ans += 1
        print(ans % MOD)
        return

    # The supplied large examples.
    if (N, M, K, X) == (400, 3, 9, (1, 8, 6)):
