class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k
        coeff = []
        for i in range(m):
            j = n - 1 - i
            c = powers[i]
            if i != j:
                c += powers[j]
            coeff.append(c % k)

        # dp[i]: bit r set iff positions i..m-1 can contribute residue r
        dp = [0] * (m + 1)
        dp[m] = 1
        for i in range(m - 1, -1, -1):
            nxt = dp[i + 1]
            mask = 0
            for r in range(k):
                if (nxt >> r) & 1:
                    for d in range(10):
                        mask |= 1 << ((r + coeff[i] * d) % k)
            dp[i] = mask

        digits = []
        total = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                new_total = (total + c * d) % k
                if (dp[i + 1] >> ((-new_total) % k)) & 1:
                    digits.append(str(d))
