class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            value = powers[i]
            if i != j:
                value += powers[j]
            coeff.append(value % k)

        # dp[i] is a bitmask of residues achievable by positions i onward.
        dp = [0] * (m + 1)
        dp[m] = 1  # residue zero
        for i in range(m - 1, -1, -1):
            mask = 0
            next_mask = dp[i + 1]
            for residue in range(k):
                if (next_mask >> residue) & 1:
                    for digit in range(10):
                        mask |= 1 << ((residue + coeff[i] * digit) % k)
            dp[i] = mask

        digits = []
        total = 0
        for i, c in enumerate(coeff):
            smallest = 1 if i == 0 else 0
            for digit in range(9, smallest - 1, -1):
                new_total = (total + c * digit) % k
                needed = (-new_total) % k
                if (dp[i + 1] >> needed) & 1:
                    digits.append(str(digit))
                    total = new_total
                    break

        half = ''.join(digits)
        if n % 2:
            return half + half[-2::-1]
        return half + half[::-1]

