import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    functions = [(data[i], data[i + 1]) for i in range(2, len(data), 2)]

    # For any two functions, their preferred relative order is independent
    # of the input value. Inner-to-outer order is ascending (A - 1) / B.
    functions.sort(key=lambda f: (f[0] - 1) / f[1])

    dp = [None] * (k + 1)
    dp[0] = 1
    for a, b in functions:
        for chosen in range(k, 0, -1):
            if dp[chosen - 1] is not None:
                value = a * dp[chosen - 1] + b
                if dp[chosen] is None or value > dp[chosen]:
                    dp[chosen] = value
    print(dp[k])

if __name__ == '__main__':
    main()

