class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        answer = len(s)  # Delete every character.
        for target in range(1, max(counts) + 1):
            # State 0: current letter is absent; state 1: it occurs target times.
            dp = [counts[0], abs(counts[0] - target)]
            capacities = [counts[0], max(0, counts[0] - target)]

            for i in range(1, 26):
                next_dp = [float('inf'), float('inf')]
                for previous_state in range(2):
                    for state in range(2):
                        if state == 0:
                            cost = counts[i]
                            deficit = 0
                        else:
                            cost = abs(counts[i] - target)
                            deficit = max(0, target - counts[i])

                        # Shift surplus from the previous letter into this one.
                        saved = min(capacities[previous_state], deficit)
                        next_dp[state] = min(
                            next_dp[state], dp[previous_state] + cost - saved
                        )

                dp = next_dp
                capacities = [counts[i], max(0, counts[i] - target)]

            answer = min(answer, dp[0], dp[1])

        return answer

