from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for u in order:
            for v, _ in graph[u]:
                if parent[v] == -1:
                    parent[v] = u
                    order.append(v)

        # dp0[u]: best subtree value if the edge to the parent is absent.
        # dp1[u]: best subtree value if the edge to the parent is present.
        dp0 = [0] * n
        dp1 = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp0[v]
                    gains.append(w + dp1[v] - dp0[v])

            gains.sort(reverse=True)
            total = base
            for gain in gains[:k]:
                if gain > 0:
                    total += gain
            dp0[u] = total

            total = base
            for gain in gains[:k - 1]:
                if gain > 0:
                    total += gain
            dp1[u] = total

        return dp0[0]

