from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        pieces = [part for part in p.split('*') if part]
        if not pieces:
            return 0

        def occurrences(pattern):
            m = len(pattern)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = prefix[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                prefix[i] = j

            found = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = prefix[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    found.append(i - m + 1)
                    j = prefix[j - 1]
            return found

        starts = [occurrences(part) for part in pieces]
        if any(not positions for positions in starts):
            return -1

        best = len(s) + 1
        for start in starts[0]:
            end = start + len(pieces[0])
            for i in range(1, len(pieces)):
                positions = starts[i]
                j = bisect_left(positions, end)
                if j == len(positions):
                    break
                end = positions[j] + len(pieces[i])
            else:
                best = min(best, end - start)

        return best if best <= len(s) else -1

