from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder, visiting children in increasing order.
        postorder = []
        stack = [(0, False)]
        while stack:
            v, exiting = stack.pop()
            if exiting:
                postorder.append(v)
            else:
                stack.append((v, True))
                for child in reversed(children[v]):
                    stack.append((child, False))

        position = [0] * n
        for i, v in enumerate(postorder):
            position[v] = i

        subtree_size = [1] * n
        for v in postorder:
            p = parent[v]
            if p != -1:
                subtree_size[p] += subtree_size[v]

        text = ''.join(s[v] for v in postorder)

        # Manacher radii: d1[i] is the odd-radius, d2[i] the even-radius
        # centered immediately before i.
        d1 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(d1[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        d2 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(d2[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            d2[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for v in range(n):
            r = position[v]
            length = subtree_size[v]
            l = r - length + 1
            if length & 1:
                center = (l + r) // 2
                answer[v] = d1[center] >= length // 2 + 1
            else:
                center = (l + r + 1) // 2
                answer[v] = d2[center] >= length // 2
        return answer

