class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def score(values):
            if not values:
                return 0
            g = l = values[0]
            for x in values[1:]:
                g = gcd(g, x)
                l = l // gcd(l, x) * x
            return g * l

        best = score(nums)
        for i in range(len(nums)):
            best = max(best, score(nums[:i] + nums[i + 1:]))
        return best

