from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        # Each index i contributes a line nums[i] * x + dp[i] - i * nums[i].
        # Querying at x=j gives the best score for reaching j.
        tree = [None] * (4 * n)

        def add(node: int, left: int, right: int, line: tuple) -> None:
            current = tree[node]
            if current is None:
                tree[node] = line
                return

            mid = (left + right) // 2
            if line[0] * mid + line[1] > current[0] * mid + current[1]:
                tree[node], line = line, current
                current = tree[node]

            if left == right:
                return
            if line[0] * left + line[1] > current[0] * left + current[1]:
                add(node * 2, left, mid, line)
            elif line[0] * right + line[1] > current[0] * right + current[1]:
                add(node * 2 + 1, mid + 1, right, line)

        def query(node: int, left: int, right: int, x: int) -> int:
            line = tree[node]
            best = line[0] * x + line[1] if line is not None else -10**30
            if left == right:
                return best
            mid = (left + right) // 2
            if x <= mid:
                return max(best, query(node * 2, left, mid, x))
            return max(best, query(node * 2 + 1, mid + 1, right, x))

        add(1, 0, n - 1, (nums[0], 0))
        result = 0
        for j in range(1, n):
            result = query(1, 0, n - 1, j)
            add(1, 0, n - 1, (nums[j], result - j * nums[j]))
        return result

