from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        count = Counter(nums)

        for outlier in sorted(nums, reverse=True):
            remainder = total - outlier
            if remainder % 2 != 0:
                continue

            special_sum = remainder // 2
            needed = 2 if special_sum == outlier else 1
            if count[special_sum] >= needed:
                return outlier

        return 0

