from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        dp = [1] * n  # Bit s is set iff sum s is achievable for this index.

        if all(x == 0 for x in nums):
            return 0

        for k, (left, right, val) in enumerate(queries, 1):
            for i in range(left, right + 1):
                dp[i] |= dp[i] << val
                dp[i] &= (1 << (nums[i] + 1)) - 1

            if all((dp[i] >> nums[i]) & 1 for i in range(n)):
                return k

        return -1

