class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        digits = len(str(n))
        low = 10 ** (digits - 1)
        high = 10 ** digits

        is_prime = bytearray(b'\x01') * high
        if high > 0:
            is_prime[0] = 0
        if high > 1:
            is_prime[1] = 0
        for p in range(2, int((high - 1) ** 0.5) + 1):
            if is_prime[p]:
                start = p * p
                is_prime[start:high:p] = b'\x00' * (((high - 1 - start) // p) + 1)

        if is_prime[n] or is_prime[m]:
            return -1

        inf = 10**30
        dist = {n: n}
        heap = [(n, n)]
        places = [10 ** i for i in range(digits)]

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            for place in places:
                digit = (x // place) % 10
                if digit < 9:
                    y = x + place
                    if y < high and not is_prime[y]:
                        nc = cost + y
                        if nc < dist.get(y, inf):
                            dist[y] = nc
                            heapq.heappush(heap, (nc, y))
                if digit > 0:
                    y = x - place
                    if y >= low and not is_prime[y]:
                        nc = cost + y
                        if nc < dist.get(y, inf):
                            dist[y] = nc
                            heapq.heappush(heap, (nc, y))
        return -1

