from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] is the LCP of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0
        for i in range(1, n - 1):
            # nums1 is a prefix of nums2; then every legal ending of nums2 works.
            if z[i] >= i:
                answer += n - i - 1
                continue

            # Otherwise test nums2 being a prefix of nums3. For a gap d,
            # this is equivalent to the LCP at suffixes i and i+d being >= d.
            # A nonempty nums3 also requires 2*d <= (n-i-1).
            length = n - i
            zz = [0] * length
            left = right = 0
            for d in range(1, (length + 1) // 2):
                if d < right:
                    zz[d] = min(right - d, zz[d - left])
                while d + zz[d] < length and nums[i + zz[d]] == nums[i + d + zz[d]]:
                    zz[d] += 1
                if d + zz[d] > right:
                    left, right = d, d + zz[d]
                if zz[d] >= d:
                    answer += 1
        return answer

