            for a, b in states
        }

        for i in range(1, n // 2):
            ndp = {}
            for a, b in states:
                pair_cost = cost[i][a] + cost[n - 1 - i][b]
                best = min(
                    dp[(x, y)]
                    for x, y in states
                    if x != a and y != b
