                    if x != a and y != b
                )
                ndp[(a, b)] = pair_cost + best
            dp = ndp

        return min(dp.values())

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j
        base = s.count('1')
        best = 0
        for k in range(2, len(runs) - 1, 2):
            # Runs are alternating, with 1-runs at even indexes (0-based).
            if runs[k][0] == '1':
                best = max(best, runs[k - 1][1] + runs[k + 1][1])
        return base + best

